using ECommerce.Domain.Common;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ECommerce.Infrastructure.Persistence.Configurations;

/// <summary>Convention shared by every e-commerce table so the base <c>Entity</c> maps identically.</summary>
public static class EntityBaseConfiguration
{
    public static void ConfigureBaseProperties<TEntity>(EntityTypeBuilder<TEntity> builder)
        where TEntity : Entity
    {
        builder.HasKey(x => x.Id);

        // Identifiers are generated by the domain, never by the database.
        builder.Property(x => x.Id).ValueGeneratedNever();

        builder.Property(x => x.CreatedAt).IsRequired();
        builder.Property(x => x.UpdatedAt);
        builder.Property(x => x.IsDeleted).HasDefaultValue(false);
    }
}